const std = @import("std");
const zml = @import("zml");

// Generated by zmlsmith from seed 500203.
test "fmod_non_f32" {
    const platform = zml.testing.env();
    const allocator = std.testing.allocator;
    const io = std.testing.io;

    const Local = struct {
        fn forward(x0: zml.Tensor) [1]zml.Tensor {
            const x1 = x0.fmod(2);
            _ = &x1;
            return .{x1};
        }
    };

    const x0: zml.Tensor = .fromShape(zml.Shape.init(.{ .k = 4 }, .f16));
    var exe = try zml.module.compile(allocator, io, Local.forward, .{x0}, platform, .{});
    defer exe.deinit();

    try zml.testing.expectEqualShapes(zml.Shape.init(.{ .k = 4 }, .f16), exe.output_shapes[0]);

    var b0: zml.Buffer = try .fromBytes(io, platform, x0.shape(), .replicated, &[_]u8{
        0, 0, 0, 0, 0, 0, 0, 0,
    });
    defer b0.deinit();
    var res = try zml.testing.autoCall(allocator, io, &exe, Local.forward, .{b0});
    defer for (&res) |*r| r.deinit();

    {
        const expected_data align(16) = [_]u8{
            0, 0, 0, 0, 0, 0, 0, 0,
        };
        const expected: zml.Slice = .init(zml.Shape.init(.{ .k = 4 }, .f16), @as([]const u8, &expected_data));
        try zml.testing.expectClose(io, expected, res[0], .exact_match);
    }
}
